package ru.neverland.townycrime;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;
import com.palmergames.bukkit.towny.TownyAPI;
import com.palmergames.bukkit.towny.object.Town;
import ru.neverland.core.*;
import static ru.neverland.townycrime.CrimePatrols.*;
/** Optional player patrol log; no salary, crime reduction, suspect assignment or monetary operation. */
public final class CrimePatrolService {
    private record Cell(int x,int z){}
    private record District(String id,String name,UUID world,int size,Set<Cell> cells){}
    private record Cached(Map<String,Object> report,long at,long revision){}
    private final JavaPlugin plugin;private final CrimePatrolRepository repository;private final LinkedHashMap<UUID,Incident> pending=new LinkedHashMap<>();private final AtomicReference<Map<UUID,Long>> watched=new AtomicReference<>(Map.of());
    private volatile Map<UUID,Map<String,Object>> evidence=Map.of();private volatile Map<UUID,Cached> reports=Map.of();private volatile State published=State.empty();private volatile boolean enabled,closed;private long warned;
    public CrimePatrolService(JavaPlugin plugin,CrimePatrolRepository repository){this.plugin=plugin;this.repository=repository;reload();publish(repository.state());}
    public void reload(){enabled=Boolean.TRUE.equals(plugin.getConfig().get("patrols.enabled",true));reports=Map.of();}
    private void publish(State value){published=value;var next=new HashMap<UUID,Map<String,Object>>();value.incidents().forEach((id,event)->next.put(id,event.evidence()));evidence=Map.copyOf(next);reports=Map.of();}
    private CompletionStage<State> commit(State before,State next){return repository.commit(before,next).thenApply(value->{publish(value);return value;});}
    public Optional<Map<String,Object>> incidentEvidence(UUID id){return closed||!enabled||!repository.readable()?Optional.empty():Optional.ofNullable(evidence.get(id));}
    public boolean allowed(Player player,UUID town){var resident=TownyAPI.getInstance().getResident(player.getUniqueId());return player.hasPermission("neverlandtownycrime.admin")||player.hasPermission("neverlandtownycrime.use")&&resident!=null&&resident.getTownOrNull()!=null&&resident.getTownOrNull().getUUID().equals(town);}
    public boolean manager(Player player,UUID town){if(player.hasPermission("neverlandtownycrime.admin"))return true;var resident=TownyAPI.getInstance().getResident(player.getUniqueId());var city=TownyAPI.getInstance().getTown(town);return player.hasPermission("neverlandtownycrime.manage")&&resident!=null&&city!=null&&resident.getTownOrNull()==city&&(city.getMayor()==resident||CouncilAccess.allows(player,town,"justice"));}
    public Town ownTown(Player player){var resident=TownyAPI.getInstance().getResident(player.getUniqueId());var town=resident==null?null:resident.getTownOrNull();if(town==null)throw new IllegalArgumentException("Вы не состоите в городе");return town;}
    private void gate(){if(closed||!enabled||!repository.writable())throw new IllegalArgumentException("Патрули временно недоступны; городские ресурсы не изменены.");}
    private Map<String,District> districts(UUID town)throws Exception{
        var api=ApiServices.require("NeverLandTownyDistricts","ru.neverland.townydistricts.api.TownyDistrictsApi","patrolLayout");
        var raw=(Map<?,?>)api.invoke("patrolLayout",new Class<?>[]{UUID.class},town);long now=System.currentTimeMillis();
        if(!Boolean.TRUE.equals(raw.get("available"))||!Boolean.FALSE.equals(raw.get("pending"))||!town.toString().equals(raw.get("town"))||!(raw.get("sourceAt") instanceof Long at)||now<at||now-at>15_000||!(raw.get("cellSize")instanceof Integer size)||size<1||size!=com.palmergames.bukkit.towny.object.Coord.getCellSize()||!(raw.get("rows")instanceof List<?> rows)||rows.size()>256)throw new IllegalArgumentException("Свежие границы районов недоступны; повторите после обновления.");
        var values=new TreeMap<String,District>();int total=0;for(Object item:rows){if(!(item instanceof Map<?,?> row)||!(row.get("id") instanceof String id)||!id.matches("[a-z0-9_-]{1,32}")||!(row.get("name")instanceof String name)||!(row.get("world")instanceof String world)||!(row.get("cells")instanceof List<?> cells)||cells.isEmpty()||cells.size()>4096)throw new IllegalArgumentException("Неверные сведения о границах района");total+=cells.size();if(total>16_384)throw new IllegalArgumentException("Слишком большая площадь районов");var positions=new HashSet<Cell>();for(Object point:cells){if(!(point instanceof Map<?,?> cell)||!(cell.get("x")instanceof Integer x)||!(cell.get("z")instanceof Integer z)||!positions.add(new Cell(x,z)))throw new IllegalArgumentException("Неверный участок района");}if(values.putIfAbsent(id,new District(id,CrimePatrols.text(name,1,48),UUID.fromString(world),size,Set.copyOf(positions)))!=null)throw new IllegalArgumentException("Повтор района");}return Map.copyOf(values);
    }
    /** Towny metadata lookup only; no world block access or region load. */
    private void physical(UUID town,District district){var world=org.bukkit.Bukkit.getWorld(district.world());if(world==null)throw new IllegalArgumentException("Мир района недоступен");for(Cell cell:district.cells()){var block=TownyAPI.getInstance().getTownBlock(new com.palmergames.bukkit.towny.object.WorldCoord(world,cell.x(),cell.z()));if(block==null||block.getTownOrNull()==null||!town.equals(block.getTownOrNull().getUUID()))throw new IllegalArgumentException("Границы города изменились; дождитесь обновления районов.");}}
    public CompletionStage<String> assign(Player actor,String district,UUID worker)throws Exception{try(var guard=SuiteState.guard()){gate();var town=ownTown(actor);if(!allowed(actor,town.getUUID())||!manager(actor,town.getUUID()))throw new IllegalArgumentException("Назначает мэр или уполномоченный городской суд.");var selected=districts(town.getUUID()).get(district);if(selected==null)throw new IllegalArgumentException("Район не найден в городе.");physical(town.getUUID(),selected);var resident=TownyAPI.getInstance().getResident(worker);if(resident==null||resident.getTownOrNull()!=town)throw new IllegalArgumentException("Исполнитель должен быть жителем города.");var before=repository.state();var value=new Patrol(UUID.randomUUID(),town.getUUID(),district,selected.name(),worker,resident.getName(),actor.getUniqueId(),System.currentTimeMillis(),Phase.ASSIGNED,"",null,0,1);if(!manager(actor,town.getUUID())||!allowed(actor,town.getUUID())||resident.getTownOrNull()!=town)throw new IllegalArgumentException("Права или состав города изменились.");var fresh=districts(town.getUUID()).get(district);if(!selected.equals(fresh))throw new IllegalArgumentException("Район изменился; повторите назначение.");physical(town.getUUID(),fresh);return commit(before,before.patrol(value)).thenApply(saved->"Патруль назначен и сохранён: "+value.id());}}
    public CompletionStage<String> finish(Player actor,UUID id,boolean cancel,String text)throws Exception{try(var guard=SuiteState.guard()){gate();var before=repository.state();var value=before.patrols().get(id);if(value==null||!allowed(actor,value.town()))throw new IllegalArgumentException("Патруль недоступен.");boolean manage=manager(actor,value.town());if(cancel&&!manage||!cancel&&!manage&&!value.worker().equals(actor.getUniqueId()))throw new IllegalArgumentException("Отчёт сдаёт назначенный житель; отменяет управляющий города.");
        if(!cancel){var city=TownyAPI.getInstance().getTown(value.town());if(city==null||!city.hasResident(value.worker()))throw new IllegalArgumentException("Назначенный житель вышел из города; управляющий может отменить патруль.");var selected=districts(value.town()).get(value.district());if(selected==null)throw new IllegalArgumentException("Район удалён или недоступен; управляющий может отменить патруль.");physical(value.town(),selected);if(!manage){var where=actor.getLocation();if(!selected.world().equals(where.getWorld().getUID())||!selected.cells().contains(new Cell(Math.floorDiv(where.getBlockX(),selected.size()),Math.floorDiv(where.getBlockZ(),selected.size()))))throw new IllegalArgumentException("Для отчёта придите в назначенный район.");}}

        if(!allowed(actor,value.town())||cancel&&!manager(actor,value.town())||!cancel&&!manager(actor,value.town())&&!value.worker().equals(actor.getUniqueId()))throw new IllegalArgumentException("Полномочия изменились.");if(!cancel){var fresh=districts(value.town()).get(value.district());if(fresh==null)throw new IllegalArgumentException("Район изменился; повторите отчёт.");physical(value.town(),fresh);var city=TownyAPI.getInstance().getTown(value.town());if(city==null||!city.hasResident(value.worker()))throw new IllegalArgumentException("Исполнитель больше не житель города.");if(!manager(actor,value.town())){var where=actor.getLocation();if(!fresh.world().equals(where.getWorld().getUID())||!fresh.cells().contains(new Cell(Math.floorDiv(where.getBlockX(),fresh.size()),Math.floorDiv(where.getBlockZ(),fresh.size()))))throw new IllegalArgumentException("Для отчёта придите в назначенный район.");}}var next=value.finish(cancel?Phase.CANCELLED:Phase.COMPLETED,actor.getUniqueId(),text,System.currentTimeMillis());return commit(before,before.patrol(next)).thenApply(saved->cancel?"Отмена патруля сохранена. Штрафов нет.":"Отчёт сохранён. Это сообщение участника, а не доказательство вины.");}}
    public void observe(CrimeState state){if(closed||!enabled||!repository.writable())return;Incident.confirmed(state).ifPresent(value->{if(evidence.containsKey(value.id()))return;if(pending.size()<512||pending.containsKey(value.id()))pending.put(value.id(),value);else warn("Очередь журнала происшествий заполнена; основная симуляция продолжает работать");});}
    public void tick(){if(closed)return;reloadEnabled();if(enabled&&repository.writable()&&!repository.busy()&&!pending.isEmpty()){var before=repository.state();try{var next=before.observe(List.copyOf(pending.values()));var captured=new HashSet<>(pending.keySet());commit(before,next).whenComplete((saved,error)->{if(error!=null)plugin.getLogger().warning("Не удалось подтвердить журнал патрулей: "+error.getMessage());});captured.forEach(pending::remove);}catch(RuntimeException error){warn("Журнал происшествий ожидает проверки: "+error.getMessage());}}long now=System.nanoTime();for(var entry:watched.get().entrySet())if(now-entry.getValue()<120_000_000_000L)capture(entry.getKey());}
    private void reloadEnabled(){boolean next=Boolean.TRUE.equals(plugin.getConfig().get("patrols.enabled",true));if(next!=enabled){enabled=next;reports=Map.of();}}
    private void warn(String message){long now=System.currentTimeMillis();if(now-warned>60_000){warned=now;plugin.getLogger().warning(message);}}
    private void watch(UUID town){long now=System.nanoTime();while(true){var old=watched.get();var next=new HashMap<>(old);next.entrySet().removeIf(e->now-e.getValue()>120_000_000_000L);if(next.size()>=128&&!next.containsKey(town))next.remove(next.entrySet().stream().min(Map.Entry.comparingByValue()).orElseThrow().getKey());next.put(town,now);if(watched.compareAndSet(old,Map.copyOf(next)))return;}}
    public Map<String,Object> report(UUID town){if(town==null||closed||!enabled||!repository.readable())return unavailable("Патрули временно отключены или журнал недоступен");watch(town);var value=reports.get(town);return value==null||value.revision()!=published.revision()||System.nanoTime()-value.at()>120_000_000_000L?Map.of("available",false,"pending",true,"issue","Сведения готовятся","rows",List.of()):value.report();}
    public void refresh(UUID town){try(var guard=SuiteState.guard()){reloadEnabled();if(town==null||closed)return;watch(town);capture(town);}}
    private void capture(UUID town){var image=published;Map<String,Object> result;if(!enabled||!repository.readable())result=unavailable("Патрули временно недоступны; штрафов нет");else if(TownyAPI.getInstance().getTown(town)==null)result=unavailable("Город больше не существует");else{Map<String,District> catalog=Map.of();String issue="";try{catalog=districts(town);}catch(Exception|LinkageError error){issue="Районы недоступны; новые назначения ожидают восстановления";}var ids=catalog.keySet();var rows=image.patrols().values().stream().filter(p->p.town().equals(town)).sorted(Comparator.comparingInt((Patrol p)->p.phase()==Phase.ASSIGNED?0:1).thenComparing(Comparator.comparingLong(Patrol::created).reversed()).thenComparing(Patrol::id)).limit(256).map(p->Map.<String,Object>of("id",p.id().toString(),"district",p.district(),"districtName",p.districtName(),"worker",p.worker().toString(),"workerName",p.workerName(),"phase",p.phase().name(),"report",p.report(),"created",p.created(),"closed",p.closed(),"districtReady",ids.contains(p.district()))).toList();var incidents=image.incidents().values().stream().filter(i->i.town().equals(town)).sorted(Comparator.comparingLong(Incident::created).reversed().thenComparing(Incident::id)).limit(256).map(Incident::evidence).toList();var areas=catalog.values().stream().sorted(Comparator.comparing(District::id)).map(d->Map.of("id",d.id(),"name",d.name())).toList();result=Map.of("available",true,"pending",false,"issue",issue,"districtsReady",issue.isEmpty(),"districts",areas,"rows",rows,"incidents",incidents,"writable",repository.writable());}var next=new HashMap<>(reports);next.keySet().retainAll(watched.get().keySet());next.put(town,new Cached(result,System.nanoTime(),image.revision()));reports=Map.copyOf(next);}
    private static Map<String,Object> unavailable(String issue){return Map.of("available",false,"pending",false,"issue",issue,"rows",List.of(),"incidents",List.of());}
    public CompletionStage<Void> prepareClose(){closed=true;reports=Map.of();watched.set(Map.of());return repository.prepareClose();}public void awaitClosed(){repository.awaitClosed();}
}
